import{_ as i,l,o as e,c as E,v as t,p as o,x as n,d as s,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const G=JSON.parse('{"title":"EAGLE-3","description":"","frontmatter":{"title":"EAGLE-3","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eagle-3.md","filePath":"llm/eagle-3.md","lastUpdated":1789023840000}'),m={name:"llm/eagle-3.md"};function p(g,a,c,L,d,u){const r=l("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="eagle-3" tabindex="-1">EAGLE-3 <a class="header-anchor" href="#eagle-3" aria-label="Permalink to &quot;EAGLE-3&quot;">​</a></h1><div class="epigraph"><p>特征预测是额外约束：数据加多了，第一步 token 接受率会涨，第二步却因为预测特征偏离训练集而塌掉；训练时把多步草稿测一遍，才能放开直接预测 token。</p><footer>—— Li, Wei, Zhang, Zhang, EAGLE-3: Scaling up Inference Acceleration of Large Language Models via Training-Time Test, NeurIPS 2025</footer></div><p><a href="/llm/eagle">EAGLE</a> 在目标模型倒二层特征上做自回归外推，再用冻结词头变成草稿，EAGLE-2 按置信度长动态树。这条路接受率已经高，但 Li、Wei、Zhang、Zhang 观察到：<strong>把草稿训练数据从 ShareGPT 量级往上堆，加速比几乎不涨。</strong> 他们把瓶颈写成特征预测约束：损失里既有 \\(l_{\\mathrm{fea}}\\) 又有 \\(l_{\\mathrm{token}}\\)，草稿被按在「下一特征必须像目标倒二层」上，表达力不够吃数据。EAGLE-3 丢掉特征拟合，改为直接预测 token，并用 <strong>training-time test</strong> 在训练里模拟多步推理输入；输入也不再只用顶层特征，而是融合低、中、高三层。论文报告相对 EAGLE-2 约 1.4× 的延迟加速，峰值加速比约 6.5×；在 SGLang、batch 64 时吞吐约 1.38×。验证仍走拒绝采样，声明无损。本篇写 3 相对 1/2 改了什么，不把 DeepSeek 预训练 <a href="/llm/mtp">MTP</a> 说成 EAGLE-3。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投机解码用便宜草稿猜若干 token，目标模型一次并行校验。<a href="/llm/speculative-decoding">投机解码原理</a> 保证分布；加速取决于接受长度。EAGLE 用目标模型自己的顶层特征当条件，草稿只需学「特征怎么走一步」，比独立小模型容易。标题里的 feature uncertainty 用错开的 token 嵌入解开。</p><p>数据缩放在目标模型上成立：Llama 7B/8B 从 1T 到 15T，架构几乎不动，能力涨。把同一逻辑搬到 EAGLE，作者看到的是平坦曲线。拆开看：去掉 \\(l_{\\mathrm{fea}}\\) 之后，<strong>第一步</strong>草稿的 \\(0\\)-\\(\\alpha\\) 随数据明显上升；但第一步的输出 \\(\\hat a_{t+1}\\) 不再贴近真值特征 \\(f_{t+1}\\)，第二步的输入分布相对训练偏移，<strong>\\(1\\)-\\(\\alpha\\) 崩掉</strong>。特征损失本来是在「只训一步」时给多步能力的拐杖；拿掉拐杖却不改训练过程，多步链就断。</p><h3 id="顶层特征只够预测下一个词" tabindex="-1">顶层特征只够预测下一个词 <a class="header-anchor" href="#顶层特征只够预测下一个词" aria-label="Permalink to &quot;顶层特征只够预测下一个词&quot;">​</a></h3><p>词头若满秩，倒二层与下一 token 的 logits 一一对应，顶层特征是「下一词」的充分统计，不是「下下词」的。EAGLE 与 Medusa 都靠这层，远位置等于在下一词语境里猜更远的词。HASS 仍做特征预测，用训练时模拟来缓解误差累积，输入仍必须是顶层。EAGLE-3 的主张是：一旦不再回归特征，输入就可以换成任意层的融合——浅层位置、中层句法、顶层词表前表征可以一起进草稿。</p><p><span class="marginnote">EAGLE-3 与 EAGLE-2 的动态树兼容，改的是草稿怎么训、吃什么特征，不是另做一套验证。报加速必须带温度、任务与是否树形草稿；不要把 Vicuna-13B、temperature 0 的峰值抄成所有模型的常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推理仍是草稿–验证交替。Prefill 或上一轮验证时，目标模型前向留下低、中、高层特征 \\(l,m,h\\)，拼接后经全连接压回隐空间宽度 \\(k\\)，得到融合特征 \\(g\\)。草稿是<strong>一层</strong>解码器：把 \\(g\\) 与<strong>已采样 token 的嵌入</strong>再拼、再投影，输出无约束向量 \\(a\\)，过目标词头得到草稿分布。第一步还能复用目标算好的 \\(g\\)；第二步起，尚未被目标校验的位置没有 \\(g\\)，用上一步的 \\(a\\) 顶替，并拼上新采样 token 的嵌入。这与 EAGLE「特征序列 + 错开 token」同构，只是序列里混进了草稿自己的 \\(a\\)。</p><h3 id="training-time-test-训练里走第二、第三步" tabindex="-1">Training-time test：训练里走第二、第三步 <a class="header-anchor" href="#training-time-test-训练里走第二、第三步" aria-label="Permalink to &quot;Training-time test：训练里走第二、第三步&quot;">​</a></h3><p>只在真值特征上训一步，推理却要把 \\(a\\) 喂回去，分布必然错位。EAGLE-3 在训练时对同一截数据做原生一步，再把模型自己的预测当后续步的输入，注意力掩码改成树状依赖：第一步是标准下三角；后续步里，草稿 token 作为 query 时，对原始前缀用点积取对应位置，草稿之间按树边可见。HASS 也改掩码，但动机是减轻特征误差累积，仍保留 \\(l_{\\mathrm{fea}}\\)。EAGLE-3 的动机是去掉约束、放开输入；去掉 \\(l_{\\mathrm{fea}}\\) 之后，作者观察到草稿训练数据量与加速比之间出现原先没有的缩放曲线。</p>',13)),(e(),o(h,null,{default:n(()=>[A(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22%E7%9B%AE%E6%A0%87%E5%89%8D%E5%90%91%22%5D%20--%3E%20LMH%5B%22%E4%BD%8E%20%2F%20%E4%B8%AD%20%2F%20%E9%AB%98%E5%B1%82%E7%89%B9%E5%BE%81%22%5D%0A%20%20LMH%20--%3E%20FC%5B%22%E6%8B%BC%E6%8E%A5%E5%B9%B6%E6%8A%95%E5%BD%B1%E6%88%90%20g%22%5D%0A%20%20FC%20--%3E%20D%5B%22%E5%8D%95%E5%B1%82%E8%8D%89%E7%A8%BF%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20E%5B%22%E5%B7%B2%E9%87%87%E6%A0%B7%20token%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20A%5B%22%E8%BE%93%E5%87%BA%20a%22%5D%0A%20%20A%20--%3E%20H%5B%22%E5%86%BB%E7%BB%93%E8%AF%8D%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20S%5B%22%E8%8D%89%E7%A8%BF%20token%22%5D%0A%20%20S%20--%3E%20D%0A%20%20A%20--%3E%20D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实验覆盖 Vicuna-13B、Llama-3.1-Instruct 8B、Llama-3.3-Instruct 70B、DeepSeek-R1-Distill-Llama 8B；任务为 MT-bench、HumanEval、GSM8K、Alpaca、CNN/Daily Mail，同一套草稿权重不按任务微调。Temperature 0 时，Vicuna-13B 上 EAGLE-3 平均加速约 5.51×、平均接受长度 \\(\\tau\\approx 6.62\\)，对照 EAGLE-2 约 4.22× / 4.83；HumanEval 上该档可到约 6.47×。Llama-3.1 8B 平均约 4.44× 对 EAGLE-2 的 3.23×。405B / 671B 因算力未测。草稿数据相对 EAGLE 大约 8×。SGLang 在 batch 64 给出约 40% 吞吐提升，用来反驳「大 batch 上投机一定伤吞吐」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>特征回归把草稿的输出空间钉在目标倒二层流形上，数据再多也主要在流形上拟合残差。直接预测 token 把容量还给词表交叉熵；training-time test 则把「推理时输入是 \\(g\\) 与 \\(a\\) 的混合物」写进训练分布，于是第二步不再是域外。多层融合补偿「顶层只有下一词信息」：远草稿步需要的规划信号更多来自中间层。动态树仍用草稿 softmax 置信度当接受率代理，与 EAGLE-2 相同，前提是新草稿仍然校准——论文用接受长度与加速比一起报，而不是只报置信度。</p><p><span class="marginnote">「无损」继承 Leviathan / Chen 的拒绝采样，不继承贪心逐 token 相同。服务端若改 typical decoding、或树先验与训练不一致，要重新论证。Medusa 在非贪心下放宽接受，论文因此不在 temperature=1 与这类方法比。</span></p><h3 id="和-eagle-1-2、hass、mtp-的分工" tabindex="-1">和 EAGLE-1/2、HASS、MTP 的分工 <a class="header-anchor" href="#和-eagle-1-2、hass、mtp-的分工" aria-label="Permalink to &quot;和 EAGLE-1/2、HASS、MTP 的分工&quot;">​</a></h3><p>EAGLE-1：特征自回归 + 静态树。EAGLE-2：同一草稿，动态树。EAGLE-3：换训练目标与输入特征，树沿用 2。HASS：仍回归特征。DeepSeek-V3 的 MTP 是预训练期顺序模块、稠密监督，推理可卸；EAGLE-3 是推理插件，目标权重冻结。Gloeckle 的独立多头是训练目标，见 <a href="/llm/multi-token-prediction-training">MTP 训练目标</a>。不要画成「3 等于预训练 MTP」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>草稿仍要为目标模型单独训，层数通常一层，还要接三层特征的挂钩；换 RMSNorm 位置或解绑词头，融合投影要重做。中间层索引是超参，论文用低/中/高三档，不是任意三层可互换。大 batch 下投机的收益来自接受长度与目标前向被拉长后的占用率，框架若不能把树验证融进连续批，数字回不到 SGLang 那张表。</p><p>推理模型（R1 蒸馏档）的长思维链改变草稿难度，论文在 GSM8K 上给出该档加速，不能直接当成「所有推理模型 5×」。训练-time test 的掩码实现容易写错成普通因果，表现为一步准、两步崩——这与当年去掉 \\(l_{\\mathrm{fea}}\\) 却不做 test 的失败模式同构。部署清单：冻结词头、三层挂钩、拒绝采样、EAGLE-2 树、与目标相同的采样器。</p><p><span class="marginnote">出处：Li et al., <em>EAGLE-3: Scaling up Inference Acceleration of Large Language Models via Training-Time Test</em>，NeurIPS 2025，arXiv:2503.01840。前作 EAGLE ICML 2024（arXiv:2401.15077）、EAGLE-2 EMNLP 2024（arXiv:2406.16858）。代码 <a href="https://github.com/SafeAILab/EAGLE%E3%80%82HASS" target="_blank" rel="noreferrer">https://github.com/SafeAILab/EAGLE。HASS</a> 见 Zhang et al. 2024；投机采样见 Leviathan et al. ICML 2023。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EAGLE-3 取消特征回归，直接预测 token，并用 training-time test 对齐多步输入分布。</li><li>草稿输入改为低/中/高层融合，不再只用倒二层。</li><li>动态树沿用 EAGLE-2；加速比随草稿数据出现可观察的缩放。</li><li>Vicuna-13B 等设置下相对 EAGLE-2 约 1.4×，峰值约 6.5×；SGLang batch 64 吞吐约 +40%。</li><li>与预训练 MTP、与仍回归特征的 HASS 不是同一方法。</li><li>出处：Li, Wei, Zhang, Zhang, NeurIPS 2025，arXiv:2503.01840。</li></ul>',12))])}const S=i(m,[["render",p]]);export{G as __pageData,S as default};
